<template>
  <AdminLayout>
    <main class="mx-auto max-w-7xl space-y-6" aria-labelledby="billing-title">
      <header class="rounded-2xl bg-slate-900 p-5 text-white shadow-sm sm:p-7"><p class="text-xs font-bold uppercase tracking-[.16em] text-blue-300">CONSULTA DE PEDIDOS</p><h1 id="billing-title" class="mt-1 text-3xl font-black">Facturación</h1><p class="mt-2 max-w-2xl text-sm text-slate-300">Revisa las solicitudes y prepara borradores. La conexión de emisión aún no está implementada.</p></header>
      <section class="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm" aria-label="Filtros de facturación"><form class="grid gap-3 sm:grid-cols-2 lg:grid-cols-6" @submit.prevent="load(1)">
        <label class="text-sm font-semibold text-slate-700 lg:col-span-2">Número de pedido o cliente<input v-model.trim="filters.search" class="field mt-1" placeholder="Número o nombre" /></label>
        <label class="text-sm font-semibold text-slate-700">Tipo solicitado<select v-model="filters.receipt_type" class="field mt-1"><option value="">Todos</option><option value="boleta">Boleta</option><option value="factura">Factura</option></select></label>
        <label class="text-sm font-semibold text-slate-700">Desde<input v-model="filters.date_from" type="date" class="field mt-1" /></label>
        <label class="text-sm font-semibold text-slate-700">Hasta<input v-model="filters.date_to" type="date" class="field mt-1" /></label>
        <label class="flex items-end gap-2 pb-2 text-sm font-semibold text-slate-700"><input v-model="filters.missing_data" type="checkbox" class="h-4 w-4 accent-blue-700" />Datos faltantes</label>
        <div class="flex gap-2 sm:col-span-2 lg:col-span-6"><Button type="submit" label="Aplicar filtros" icon="pi pi-filter" :disabled="loading" /><Button type="button" label="Limpiar" severity="secondary" outlined :disabled="loading" @click="clear" /></div>
      </form></section>
      <p v-if="error" class="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-900" role="alert">{{ error }}</p>
      <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm" aria-label="Pedidos para consulta de facturación">
        <div v-if="loading" class="p-10 text-center text-slate-600" role="status"><i class="pi pi-spin pi-spinner mr-2"></i>Cargando pedidos…</div>
        <div v-else-if="!rows.length" class="p-10 text-center text-slate-600"><i class="pi pi-file text-3xl text-slate-300"></i><p class="mt-2 font-semibold">No hay pedidos para estos filtros</p></div>
        <div v-else class="overflow-x-auto"><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="p-4">Pedido / fecha</th><th class="p-4">Cliente</th><th class="p-4">Solicitud</th><th class="p-4">Receptor</th><th class="p-4 text-right">Total</th><th class="p-4">Pago</th><th class="p-4">Datos</th><th class="p-4"></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-t border-slate-100 hover:bg-slate-50"><td class="p-4"><b>{{ row.order_number }}</b><span class="mt-1 block text-xs text-slate-500">{{ formatDate(row.created_at) }}</span></td><td class="p-4">{{ row.customer_name }}</td><td class="p-4">{{ receiptLabel(row.requested_receipt_type) }}</td><td class="p-4"><span>{{ row.requested_recipient_name || 'No registrado' }}</span><small v-if="row.requested_identity_number" class="block text-slate-500">{{ row.requested_identity_type }} · {{ row.requested_identity_number }}</small></td><td class="p-4 text-right font-semibold">S/ {{ money(row.total) }}</td><td class="p-4">{{ paymentLabel(row.payment_status) }}</td><td class="p-4"><Tag :severity="row.receipt_data_missing ? 'warn' : 'success'" :value="row.receipt_data_missing ? 'Revisar datos' : 'Solicitud registrada'" /></td><td class="p-4 text-right"><Button label="Consultar" icon="pi pi-eye" size="small" outlined @click="openDetail(row)" /></td></tr></tbody></table></div>
        <footer v-if="pagination.total" class="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 p-4 text-sm"><span>Mostrando {{ pagination.from }}–{{ pagination.to }} de {{ pagination.total }}</span><div class="flex gap-2"><Button label="Anterior" severity="secondary" outlined size="small" :disabled="loading || pagination.current_page <= 1" @click="load(pagination.current_page - 1)" /><Button label="Siguiente" severity="secondary" outlined size="small" :disabled="loading || pagination.current_page >= pagination.last_page" @click="load(pagination.current_page + 1)" /></div></footer>
      </section>
      <div v-if="detailOpen" class="fixed inset-0 z-[80] flex items-center justify-center bg-slate-950/60 p-3" role="presentation" @click.self="detailOpen = false"><section class="max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-2xl bg-white shadow-2xl" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="flex items-start justify-between gap-3 border-b p-5"><div><p class="text-xs font-bold uppercase tracking-wide text-blue-700">Consulta de Facturación</p><h2 id="detail-title" class="mt-1 text-2xl font-black">{{ detail?.order_number || 'Pedido' }}</h2></div><Button icon="pi pi-times" severity="secondary" text aria-label="Cerrar detalle" @click="detailOpen = false" /></header><div v-if="detailLoading" class="p-8 text-center" role="status">Cargando detalle…</div><div v-else-if="detail" class="space-y-5 p-5"><p class="rounded-lg bg-blue-50 p-3 text-sm text-blue-900">{{ detail.receipt_status === 'requested_not_issued' ? 'Comprobante solicitado; aún no emitido.' : 'Datos de comprobante no registrados.' }}</p><dl class="grid gap-3 sm:grid-cols-2"><div><dt class="label">Cliente</dt><dd>{{ detail.customer_name }}</dd></div><div><dt class="label">Fecha del pedido</dt><dd>{{ formatDate(detail.created_at) }}</dd></div><div><dt class="label">Tipo solicitado</dt><dd>{{ receiptLabel(detail.requested_receipt_type) }}</dd></div><div><dt class="label">Estado de pago</dt><dd>{{ paymentLabel(detail.payment_status) }}</dd></div><div><dt class="label">Receptor</dt><dd>{{ detail.requested_recipient_name || 'No registrado' }}</dd></div><div><dt class="label">Documento</dt><dd>{{ detail.requested_identity_type && detail.requested_identity_number ? `${detail.requested_identity_type} · ${detail.requested_identity_number}` : 'No registrado' }}</dd></div><div><dt class="label">Correo</dt><dd>{{ detail.requested_receipt_email || 'No registrado' }}</dd></div><div><dt class="label">Dirección de facturación</dt><dd>{{ detail.requested_billing_address || 'No registrada' }}</dd></div><div><dt class="label">Total del pedido</dt><dd class="font-bold">S/ {{ money(detail.total) }}</dd></div></dl><div><h3 class="mb-2 font-bold">Productos</h3><ul class="divide-y rounded-lg border"> <li v-for="(item, index) in detail.items || []" :key="index" class="flex justify-between gap-3 p-3 text-sm"><span>{{ item.quantity }} × {{ item.product_name }}</span><span>S/ {{ money(item.subtotal) }}</span></li></ul></div>
        <section class="space-y-3 rounded-xl border border-indigo-200 bg-indigo-50/50 p-4" aria-labelledby="drafts-title"><div class="flex flex-wrap items-center justify-between gap-2"><div><h3 id="drafts-title" class="font-bold">Documentos electrónicos</h3><p class="text-sm text-slate-600">Los borradores no son comprobantes emitidos.</p></div><Button label="Preparar borrador" icon="pi pi-file-edit" size="small" :disabled="documentBusy || !electronicEnabled || !detail.requested_receipt_type" @click="confirmPrepareDraft" /></div><p v-if="!electronicEnabled" class="text-sm text-amber-800" role="status">Módulo no habilitado comercialmente.</p><p v-else-if="!detail.requested_receipt_type" class="text-sm text-slate-700" role="status">Este pedido no tiene solicitud de boleta o factura registrada.</p><p v-if="documentError" class="text-sm text-red-700" role="alert">{{ documentError }}</p><Button v-if="versionConflict && draft" label="Cargar versión vigente" icon="pi pi-refresh" size="small" severity="secondary" outlined :disabled="documentBusy" @click="openDraft(draft.id)" /><div v-if="detail.electronic_documents?.length" class="space-y-2"><button v-for="document in detail.electronic_documents" :key="document.id" type="button" class="flex w-full items-center justify-between rounded-lg border bg-white p-3 text-left hover:border-blue-400" :disabled="documentBusy" @click="openDraft(document.id)"><span><b>{{ receiptLabel(document.document_type) }}</b><small class="block text-slate-500">Borrador · no emitido · versión {{ document.version }}</small></span><i class="pi pi-chevron-right" aria-hidden="true"></i></button></div><div v-if="draft" class="space-y-4 rounded-lg border bg-white p-4"><div class="flex flex-wrap justify-between gap-2"><div><b>{{ receiptLabel(draft.document_type) }} · Borrador</b><p class="text-sm text-amber-800">{{ taxCalculationLabel(draft.tax_calculation_status) }}</p></div><Button label="Guardar correcciones" icon="pi pi-save" size="small" :disabled="documentBusy" @click="saveDraft" /></div><p v-if="draft.amounts?.missing_fields?.length" class="rounded bg-amber-50 p-3 text-sm text-amber-900">Datos pendientes: {{ draft.amounts.missing_fields.join(', ') }}</p><p class="text-xs text-slate-500">Fuentes: datos del vendedor actuales ({{ draft.seller?.source }}); receptor y líneas del snapshot del pedido ({{ draft.recipient?.source }}, {{ draft.lines?.source }}).</p><div class="grid gap-3 sm:grid-cols-2"><label v-for="field in sellerFields" :key="`s-${field.key}`" class="text-sm font-semibold">{{ field.label }}<input v-model="draft.seller[field.key]" class="field mt-1" :aria-label="field.label" /></label><label v-for="field in recipientFields" :key="`r-${field.key}`" class="text-sm font-semibold">{{ field.label }}<input v-model="draft.recipient[field.key]" class="field mt-1" :aria-label="field.label" /></label></div><ul class="divide-y rounded border"><li v-for="(item, index) in draft.lines?.items || []" :key="index" class="flex justify-between gap-3 p-2 text-sm"><span>{{ item.quantity }} × {{ item.name || 'Nombre histórico no disponible' }}</span><span>{{ item.subtotal ?? 'Importe no disponible' }}</span></li></ul><section v-if="draft.amounts?.tax_snapshot" class="rounded-lg border bg-slate-50 p-3 text-sm"><h4 class="font-bold">Snapshot tributario del pedido</h4><p class="mt-1">Estado: {{ taxCalculationLabel(draft.tax_calculation_status) }}</p><ul class="mt-2 space-y-2"><li v-for="(item, index) in draft.lines?.items || []" :key="`tax-${index}`"><span class="font-medium">{{ item.name || 'Nombre histórico no disponible' }}</span><span v-if="item.tax?.tax_affectation"> — {{ item.tax.tax_affectation.label }}, base S/ {{ money(item.tax.base) }}, impuesto S/ {{ money(item.tax.tax) }}</span><span v-else> — afectación y cálculo pendientes</span></li></ul><p class="mt-2">IGV: S/ {{ money(draft.amounts.tax_snapshot.totals?.igv_minor) }} · IPM: S/ {{ money(draft.amounts.tax_snapshot.totals?.ipm_minor) }} · Envío: S/ {{ money(draft.amounts.tax_snapshot.shipping?.gross) }}</p><p v-if="draft.amounts.tax_snapshot.missing_fields?.includes('shipping_mixed_affectations')" class="mt-2 text-amber-900">El costo de envío de un pedido con afectaciones mixtas está pendiente de revisión contable; no se debe emitir hasta resolverlo.</p></section><p class="text-sm">Total histórico del pedido: {{ draft.currency }} {{ draft.amounts?.total ?? 'No disponible' }}</p><ol class="space-y-1 text-xs text-slate-600"><li v-for="(event, index) in draft.history || []" :key="index">{{ event.event_type }} · {{ event.actor_name }} · {{ formatDate(event.created_at) }} · v{{ event.version_to }}</li></ol></div></section><p v-if="detailError" class="text-sm text-red-700" role="alert">{{ detailError }}</p></div></section></div>
    </main>
  </AdminLayout>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue';
import { useToast } from 'primevue/usetoast';
import { useConfirm } from 'primevue/useconfirm';
import api from '@/api';
import AdminLayout from '@/layouts/AdminLayout.vue';
import Button from 'primevue/button';
import Tag from 'primevue/tag';

const toast = useToast();
const confirm = useConfirm();
const filters = reactive({ search: '', receipt_type: '', date_from: '', date_to: '', missing_data: false });
const rows = ref([]), pagination = ref({}), loading = ref(false), error = ref('');
const detailOpen = ref(false), detailLoading = ref(false), detail = ref(null), detailError = ref('');
const electronicEnabled = ref(false), documentBusy = ref(false), documentError = ref(''), draft = ref(null);
const versionConflict = ref(false);
const preparationKey = ref('');
const pendingPreparationKeys = new Map();
const sellerFields = [{ key: 'commercial_name', label: 'Nombre comercial' }, { key: 'legal_name', label: 'Razón social' }, { key: 'tax_id_type', label: 'Tipo de identificación' }, { key: 'tax_id_number', label: 'Número tributario' }, { key: 'country_code', label: 'País' }, { key: 'fiscal_address', label: 'Dirección fiscal' }];
const recipientFields = [{ key: 'document_type', label: 'Tipo de documento' }, { key: 'document_number', label: 'Número de documento' }, { key: 'name', label: 'Receptor' }, { key: 'billing_address', label: 'Dirección de facturación' }, { key: 'email', label: 'Correo' }];
function money(value) { return Number(value || 0).toLocaleString('es-PE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function formatDate(value) { return value ? new Intl.DateTimeFormat('es-PE', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'America/Lima' }).format(new Date(value)) : '—'; }
function receiptLabel(value) { return value === 'boleta' ? 'Boleta de venta' : value === 'factura' ? 'Factura' : 'No registrado'; }
function paymentLabel(value) { return ({ pending: 'Pendiente', partial: 'Parcial', approved: 'Aprobado', rejected: 'Rechazado', refunded: 'Reembolsado' })[value] || 'Sin estado'; }
function taxCalculationLabel(value) { return ({ complete: 'Cálculo tributario completo', pending_configuration: 'Pendiente de configuración o clasificación · no listo para emitir', review_required: 'Requiere revisión contable · no listo para emitir', pending_definition: 'Pedido histórico sin cálculo tributario registrado · no listo para emitir' })[value] || 'Cálculo tributario no disponible · no listo para emitir'; }
async function load(page = 1) { loading.value = true; error.value = ''; try { const params = Object.fromEntries(Object.entries({ ...filters, page }).filter(([, value]) => value !== '' && value !== false)); const response = (await api.get('/billing/orders', { params })).data; rows.value = response.data || []; pagination.value = response.meta || {}; } catch (exception) { error.value = exception.response?.data?.message || 'No se pudo cargar la bandeja.'; } finally { loading.value = false; } }
function clear() { Object.assign(filters, { search: '', receipt_type: '', date_from: '', date_to: '', missing_data: false }); load(1); }
async function refreshOrder(id) { detail.value = (await api.get(`/billing/orders/${id}`)).data.data; }
function readPreparationKey(orderId) { try { return pendingPreparationKeys.get(orderId) || sessionStorage.getItem(preparationStorageKey(orderId)) || ''; } catch { return pendingPreparationKeys.get(orderId) || ''; } }
function persistPreparationKey(orderId, key) { pendingPreparationKeys.set(orderId, key); try { sessionStorage.setItem(preparationStorageKey(orderId), key); } catch { /* La clave sigue en memoria para reintentos dentro de esta sesión. */ } }
function clearPreparationKey(orderId) { pendingPreparationKeys.delete(orderId); try { sessionStorage.removeItem(preparationStorageKey(orderId)); } catch { /* El almacenamiento de sesión es opcional. */ } }
async function openDetail(row) { detail.value = null; draft.value = null; versionConflict.value = false; preparationKey.value = readPreparationKey(row.id); detailError.value = ''; documentError.value = ''; detailOpen.value = true; detailLoading.value = true; try { await refreshOrder(row.id); electronicEnabled.value = (await api.get('/billing/electronic-invoicing/status')).data.data.commercial_enabled; } catch (exception) { detailError.value = exception.response?.data?.message || 'No se pudo cargar el pedido.'; } finally { detailLoading.value = false; } }
function preparationStorageKey(orderId) { return `billing.electronic-document.preparation.${orderId}`; }
function randomKey() { if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID(); const bytes = new Uint8Array(16); globalThis.crypto.getRandomValues(bytes); bytes[6] = (bytes[6] & 0x0f) | 0x40; bytes[8] = (bytes[8] & 0x3f) | 0x80; const hex = [...bytes].map(value => value.toString(16).padStart(2, '0')).join(''); return `${hex.slice(0,8)}-${hex.slice(8,12)}-${hex.slice(12,16)}-${hex.slice(16,20)}-${hex.slice(20)}`; }
function confirmPrepareDraft() { if (documentBusy.value || !electronicEnabled.value) return; confirm.require({ header: 'Preparar borrador', message: 'Se creará un borrador a partir de los snapshots del pedido. No se emitirá ningún comprobante. ¿Deseas continuar?', acceptLabel: 'Preparar borrador', rejectLabel: 'Cancelar', accept: prepareDraft }); }
async function prepareDraft() { if (!detail.value || documentBusy.value) return; documentBusy.value = true; documentError.value = ''; const orderId = detail.value.id; if (!preparationKey.value) { preparationKey.value = randomKey(); persistPreparationKey(orderId, preparationKey.value); } try { const response = await api.post(`/billing/orders/${orderId}/electronic-documents`, { preparation_key: preparationKey.value }); draft.value = response.data.data; preparationKey.value = ''; clearPreparationKey(orderId); await refreshOrder(orderId); } catch (exception) { documentError.value = exception.response?.data?.message || 'No se pudo confirmar la respuesta. Reintenta desde este pedido para consultar el mismo borrador.'; } finally { documentBusy.value = false; } }
async function openDraft(id) { documentBusy.value = true; documentError.value = ''; try { draft.value = (await api.get(`/billing/electronic-documents/${id}`)).data.data; versionConflict.value = false; } catch (exception) { documentError.value = exception.response?.data?.message || 'No se pudo cargar el borrador.'; } finally { documentBusy.value = false; } }
async function saveDraft() { if (!draft.value || documentBusy.value) return; documentBusy.value = true; documentError.value = ''; versionConflict.value = false; const id = draft.value.id; const orderId = detail.value.id; try { draft.value = (await api.put(`/billing/electronic-documents/${id}`, { version: draft.value.version, seller: Object.fromEntries(sellerFields.map(field => [field.key, draft.value.seller[field.key] || null])), recipient: Object.fromEntries(recipientFields.map(field => [field.key, draft.value.recipient[field.key] || null])) })).data.data; await refreshOrder(orderId); draft.value = (await api.get(`/billing/electronic-documents/${id}`)).data.data; } catch (exception) { versionConflict.value = exception.response?.status === 409; documentError.value = versionConflict.value ? 'El borrador tiene una versión más reciente. Carga la versión vigente antes de guardar.' : exception.response?.data?.message || 'No se pudo guardar el borrador.'; } finally { documentBusy.value = false; } }
onMounted(() => load());
</script>

<style scoped>
.field{min-height:2.75rem;width:100%;border:1px solid #cbd5e1;border-radius:.625rem;background:#fff;padding:.625rem .75rem;color:#0f172a}.field:focus-visible{outline:2px solid #2563eb;outline-offset:2px}.label{font-size:.72rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:#64748b}.label+dd{margin-top:.25rem;overflow-wrap:anywhere;color:#0f172a}
</style>
